from __future__ import annotations

from contextlib import contextmanager
from typing import Any, Iterator

import sqlite3

from .database import create_connection
from .runtime_config import RuntimeSettings, load_runtime_settings


class PostgresConnection:
    """Small DB-API adapter for the named parameters generated by the SQL compiler."""

    def __init__(self, connection: Any, statement_timeout_ms: int) -> None:
        self._connection = connection
        self._statement_timeout_ms = statement_timeout_ms

    def execute(self, sql: str, parameters: dict[str, Any] | None = None) -> Any:
        converted = sql
        for name in (parameters or {}):
            converted = converted.replace(f":{name}", f"%({name})s")
        cursor = self._connection.cursor()
        cursor.execute(
            "SELECT set_config('statement_timeout', %s, false)",
            (str(self._statement_timeout_ms),),
        )
        cursor.execute(converted, parameters or {})
        return cursor

    def explain(self, sql: str, parameters: dict[str, Any]) -> tuple[float, int]:
        cursor = self.execute(f"EXPLAIN (FORMAT JSON) {sql}", parameters)
        row = cursor.fetchone()
        payload = next(iter(row.values())) if isinstance(row, dict) else row[0]
        plan = payload[0]["Plan"]
        return float(plan["Total Cost"]), self._maximum_plan_rows(plan)

    def _maximum_plan_rows(self, plan: dict[str, Any]) -> int:
        return max(
            [
                int(plan.get("Plan Rows", 0)),
                *(self._maximum_plan_rows(child) for child in plan.get("Plans", ())),
            ]
        )

    def close(self) -> None:
        self._connection.close()


class StructuredStore:
    def __init__(self, settings: RuntimeSettings | None = None) -> None:
        self.settings = settings or load_runtime_settings()
        self._pool: Any | None = None

    @property
    def backend(self) -> str:
        return "postgresql" if self.settings.sql_query_database_url else "sqlite-local"

    @contextmanager
    def connection(self) -> Iterator[Any]:
        if not self.settings.sql_query_database_url:
            connection = create_connection()
            try:
                yield connection
            finally:
                connection.close()
            return

        try:
            from psycopg_pool import ConnectionPool
            from psycopg.rows import dict_row
        except ImportError as exc:
            raise RuntimeError(
                "PostgreSQL is configured but psycopg and psycopg-pool are not installed. "
                "Install backend requirements before using SQL_QUERY_DATABASE_URL."
            ) from exc

        if self._pool is None:
            self._pool = ConnectionPool(
                conninfo=self.settings.sql_query_database_url,
                min_size=self.settings.sql_pool_min_size,
                max_size=self.settings.sql_pool_max_size,
                # A restricted database role is still required. This session setting
                # adds defense in depth if deployment credentials are misconfigured.
                kwargs={
                    "row_factory": dict_row,
                    "autocommit": True,
                    "options": "-c default_transaction_read_only=on",
                },
                open=True,
            )
        with self._pool.connection() as connection:
            yield PostgresConnection(connection, self.settings.sql_statement_timeout_ms)

    def close(self) -> None:
        if self._pool is not None:
            self._pool.close()
            self._pool = None

    def readiness(self) -> dict[str, str]:
        try:
            with self.connection() as connection:
                cursor = connection.execute("SELECT 1 AS ready")
                cursor.fetchone()
        except Exception as exc:
            return {
                "status": "unavailable",
                "backend": self.backend,
                "error_type": type(exc).__name__,
            }
        return {"status": "ready", "backend": self.backend}

    def pool_metrics(self) -> dict[str, int | float]:
        if self._pool is None or not hasattr(self._pool, "get_stats"):
            return {}
        metrics: dict[str, int | float] = {
            str(key): int(value)
            for key, value in self._pool.get_stats().items()
            if isinstance(value, int)
        }
        pool_size = int(metrics.get("pool_size", 0))
        pool_available = int(metrics.get("pool_available", 0))
        if pool_size > 0:
            metrics["pool_active"] = max(0, pool_size - pool_available)
            metrics["pool_utilization_percent"] = round(
                100 * max(0, pool_size - pool_available) / pool_size,
                2,
            )
        return metrics


def open_structured_store(settings: RuntimeSettings | None = None) -> StructuredStore:
    return StructuredStore(settings=settings)
